function isFlushPayload(e){if(!e||typeof e!=`object`)return!1;let t=e;return typeof t.sessionId==`string`&&Array.isArray(t.events)}async function flushEveCliTelemetry(e){let t;try{let n=JSON.parse(e);if(!isFlushPayload(n))return;t=n}catch{return}try{await fetch(process.env.EVE_TELEMETRY_ENDPOINT??`https://telemetry.vercel.com/api/eve-cli/v1/events`,{method:`POST`,headers:{"content-type":`application/json`,"client-id":`eve-cli`,"x-eve-cli-topic-id":`generic`,"x-eve-cli-session-id":t.sessionId},body:JSON.stringify(t.events),signal:AbortSignal.timeout(1e3)})}catch{}}export{flushEveCliTelemetry};